private theorem capOfUnitHi (d g : BPair) (a b : Pos)
    (hd : d ≤ BPair.unit) (hg : BPair.unit ≤ g) :
    d.scale a ≤ g.scale b

private theorem capOfUnitLo (d g : BPair) (a b : Pos)
    (hd : BPair.unit ≤ d) (hg : BPair.unit ≤ g) :
    (g.scale b).swap ≤ d.scale a

private theorem storeE :
    BPair.ofPos enS * BPair.ofPos disconjC.e0d
      ≤ disconjC.e0n * BPair.ofPos edS

private theorem storeRate :
    6 * qLowNum (posVal enS) (posVal edS) preR nS * disconjC.qcD
      ≤ disconjC.qcN * (5 * qLowDen (posVal enS) (posVal edS) preR nS)

private theorem storeCeilT :
    BPair.ofPos 26 * BPair.ofPos disconjC.e0d
      ≤ disconjC.e0n * BPair.ofPos (tieScaleD nS)

private theorem storeRateO :
    41 * qLowNum (posVal enS) (posVal edS) 1 nO * disconjC.qcD
      ≤ disconjC.qcN * (40 * qLowDen (posVal enS) (posVal edS) 1 nO)

private theorem hmom1 :
    ((inertia.quadForm (matMul et3 et3) y1).scale (1 : Pos)).oneValue
      ((inertia.quadForm et3 y1).scale ((4 : Pos) * 3))

private theorem hmomK :
    ((inertia.quadForm (matMul et3 et3) yK).scale (1 : Pos)).oneValue
      ((inertia.quadForm et3 yK).scale ((4 : Pos) * 3))

