private def keyList : List (List Nat)

private theorem countUnitOff (x : places.Shape) (hx : x.length = 3)
    (hred : labels.reduce x = x) (hoff : countOf x [th3] = 0) :
    (dataA 3).count th3 v0 x = 0

private theorem slabShape_tail {A B : Mat} {As Bs : List Mat}
    {n0 : Nat} {nt : List Nat}
    (h : slabShape (A :: As) (B :: Bs) (n0 :: nt)) :
    slabShape As Bs nt

private theorem scaleScaleB (c : Pos) (w : BPair) (M : Mat) :
    matOneValue (matScale c (matScaleB w M))
      (matScaleB (w.scale c) M)

private theorem rowPad (c : Pos) (W : Nat) (rb : List BPair) :
    poly.oneValue ((padRow W rb).map (fun x => x.scale c))
      (padRow W (rb.map (fun x => x.scale c)))

private theorem scalePad (c : Pos) (W : Nat) (B : Mat) :
    matOneValue (matScale c (offPad W B))
      (offPad W (matScale c B))

private theorem rowPadCongr (W : Nat) {rb rb' : List BPair}
    (hl : rb.length = rb'.length) (h : poly.oneValue rb rb') :
    poly.oneValue (padRow W rb) (padRow W rb')

private theorem liftMat_nil_act (k : Nat) (w : List BPair)
    (hw : w.length = k) :
    poly.oneValue (matVec (liftMat k []) w) w

private theorem tailRead_tail {A B : Mat} {As Bs : List Mat}
    {X0 R0 : MatQ} {Xt Rt : List MatQ} {n0 : Nat} {nt : List Nat}
    (h : tailRead (A :: As) (B :: Bs) (X0 :: Xt) (R0 :: Rt) (n0 :: nt)) :
    tailRead As Bs Xt Rt nt

private theorem symP_of_sym (S : Mat) (n : Nat) (hSl : S.length = n)
    (hSr : rowsLen n S) (hsym : matOneValue S (transposeM S)) :
    symP S n

private theorem consArith (a b x y : BPair) :
    (x * (a * x + b * y) + y * (b * x)).oneValue
      (a * (x * x) + BPair.ofNat 2 * (b * (x * y)))

private theorem widthE (a b : Shape) (hba : b.length = a.length)
    (ws : List Nat) :
    (wactT lowerTable ws (exhibit b)).content.length = a.length

private theorem widthG (a : Shape) (g : HVec) (hg : g ∈ blockSpan a)
    (ws : List Nat) :
    (wactT dualTable ws g).content.length = a.length

private theorem coScale_off (Y : List HVec) (mu : List Nat)
    (hall : ∀ nu, ¬ (blockDet Y nu).oneValue BPair.unit) :
    ¬ (coScale Y mu).oneValue BPair.unit

private theorem coevG_sq (b : Shape) (W : List (List Nat))
    (mu : List Nat) :
    elim.sqAt (coevG b W mu) (coevIdx b W mu).length

private theorem unitTail_swapAdd (c : BPair) (u w : List BPair)
    (h : poly.oneValue (elim.vecScale c u) w) :
    poly.unitTail (elim.vecAdd (elim.vecScale c.swap u) w)

private theorem coevKer_kill (D E T : BPair)
    (hT : T.oneValue BPair.unit) :
    (D * (E * T)).oneValue BPair.unit

private theorem vecScale_map {α : Type} (c : BPair)
    (f : α → BPair) (l : List α) :
    elim.vecScale c (l.map f) = l.map (fun t => c * f t)

private theorem dualSys_mem (Y Z : List HVec) (d p q : Nat)
    (hp : p < d) (hq : q < d) (hpq : ¬ p = q) {a b : HVec}
    (ha : a ∈ Y) (hb : b ∈ Z) :
    dualRow Y Z p q a b ∈ dualSys Y Z d

private theorem length_gridRow (T : List Nat → elim.Mat)
    (Y Z : List HVec) (mu : List Nat) (j : Nat) :
    (gridRow T Y Z mu j).length = (groupAt Z mu).length

private theorem trip_arrange (s c A c' F w : BPair) :
    ((s * c) * A) * ((c' * F) * w)
      = (c' * w) * ((s * c) * (A * F))

private theorem dualPairs_mem (Y Z : List HVec) (y z : HVec)
    (h : (y, z) ∈ dualPairs Y Z) :
    z ∈ Z ∧ z.content = y.content

private theorem pairsAt_rowsLen (A B : List HVec) (cc : List Nat) :
    elim.rowsLen (places.monomialsAt cc).length
      ((pairsAt A B cc).map HVec.coords)

private theorem fulls_succ (d m : Nat) :
    fulls d (m + 1)
      = ground.bumpAt ((fulls d m).length - 1) (fulls d m)

private theorem sqTerm {V K cj : BPair} {p q : Pos}
    (h : V.scale p ≤ K.scale q) :
    ((V * (cj * cj)).scale p) ≤ ((K * (cj * cj)).scale q)

private theorem posLow (gn gd wn wd : Pos) :
    gn * wd * (wn * gd) * (2 * wd)
      = gd * (2 * (gn * (wd * wn) * wd))

private theorem closeStep {Z W B : BPair} {c : Pos}
    (h1 : Z ≤ W) (h2 : W.scale (2 * c) ≤ Z.scale c + B) :
    Z.scale c ≤ B

private theorem offAt {diag off : List Mat} {ns : List Nat}
    (h : greenprod.slabShape diag off ns) (i : Nat)
    (hi : i + 1 < ns.length) : i < off.length

private theorem walkOcc {dn : BPair} {sn sd cn cd : Pos}
    {Gs : List Mat} {Y0' Y0 : greenprod.MatQ}
    {Cs Cs' Ys Ys' : List greenprod.MatQ}
    {certs : List ((p : Nat × Nat) × (Pos × Pos) × (Pos × Pos)
      × Split p.2 × Split p.2 × Split p.1 × Split p.1
      × Split p.2 × Split p.2 × Split p.2 × Split p.2)}
    (h : spectator.driftWalk dn sn sd Gs cn cd Y0' Y0 Cs Cs' Ys Ys' certs)
    (hc : 0 < certs.length) : 0 < Cs.length ∧ 0 < Cs'.length

private theorem gvsApp (w : Pos) (x y : List BPair) :
    greenprod.vecScale w (x ++ y)
      = greenprod.vecScale w x ++ greenprod.vecScale w y

private theorem gvsSelf (w : Pos) (v : List BPair) :
    (dotN (greenprod.vecScale w v) (greenprod.vecScale w v)).oneValue
      ((dotN v v).scale (w * w))

private theorem tieScale (x : BPair) {g gc : BPair} {s s2 : Pos}
    (h : (g.scale s).oneValue (gc.scale s2)) :
    ((x * g).scale s).oneValue ((x * gc).scale s2)

private theorem posL3 (ca dt dh dt' s p b : Pos) :
    ca * dt * (dh * dt' * (s * (p * b)))
      = s * (ca * (dh * (dt * dt') * (p * b)))

private theorem posL3' (ca dt' dh' dt s p b : Pos) :
    ca * dt' * (dh' * dt * (s * (p * b)))
      = s * (ca * (dh' * (dt * dt') * (p * b)))

private theorem scaleMulLe {X Y F : BPair} {a b : Pos}
    (hF : BPair.unit ≤ F) (h : X.scale a ≤ Y.scale b) :
    (X * F).scale a ≤ (Y * F).scale b

private theorem stepLe {X Y F : BPair} {a b c : Pos}
    (hF : BPair.unit ≤ F) (h : X.scale a ≤ Y.scale b) :
    (X * F).scale (a * c) ≤ (Y * F).scale (b * c)

private theorem stepCongr {X Y F : BPair} {a b c : Pos}
    (h : (X.scale a).oneValue (Y.scale b)) :
    ((X * F).scale (a * c)).oneValue ((Y * F).scale (b * c))

private theorem posC1 (A B C D E F G : Pos) :
    ((A * B) * (C * D)) * (E * (F * G))
      = E * (F * (D * (G * (A * (B * C)))))

private theorem posC2 (S F P U D E G : Pos) :
    (S * (F * (P * U))) * (D * (E * G))
      = S * (G * (F * (P * (U * (D * E)))))

private theorem posC3 (e g S N M H : Pos) :
    (e * (e * g)) * (S * (N * (M * H)))
      = S * ((e * e) * (g * (H * (N * M))))

private theorem crossTrans {a b c d e f : Pos}
    (h1 : a * b ≤ c * d) (h2 : c * e ≤ f * b) :
    a * e ≤ f * d

private theorem armScaleOff {un ud N : Pos} {nk : BPair}
    {dk pk : Pos}
    (harm : nk.oneValue BPair.unit
      ∨ nk.oneValue (BPair.ofPos pk)) :
    ¬ (BPair.ofPos (dk * (N * ud)) + nk.scale un).oneValue
      BPair.unit

private theorem scalarPolar (a b X Y : BPair) :
    ((a * b) * (X * Y)).scale 2
      ≤ (a * a) * (X * X) + (b * b) * (Y * Y)

private theorem transVec_len (T : Mat) (o : Nat)
    (hTl : T.length = o) (y : List BPair) :
    ∀ k, (transVec T o y k).length = o

private theorem conjVec_len (T A : Mat) (o : Nat)
    (hTl : T.length = o) (psi : List BPair) :
    ∀ k, (conjVec T A o psi k).length = o

private theorem matNull_dotP (Z : Mat) (h : elim.matNull Z) :
    ∀ (x y : List BPair),
    (elim.dotP x (elim.matVec Z y)).oneValue BPair.unit

private theorem posSq (a b c : Pos) (k : Nat) :
    ((a * b) * Pos.pow c k) * ((a * b) * Pos.pow c k)
      = (a * a) * ((b * b) * Pos.pow (c * c) k)

private theorem posXch (p q u r v w : Pos) :
    ((p * q) * u) * ((r * v) * w)
      = ((p * v) * u) * ((r * q) * w)

private theorem crossNull_trans {x y z : PPair}
    (hy : ¬ poly.unitTail y.2) (h1 : crossNull x y)
    (h2 : crossNull y z) : crossNull x z

private theorem pprowEq_trans {a b c : List PPair}
    (hb : elim.rowOcc b = true) (h1 : pprowEq a b)
    (h2 : pprowEq b c) : pprowEq a c

private theorem ppmatEq_trans {A B C : PPMat}
    (hB : elim.matOcc B = true) (h1 : ppmatEq A B)
    (h2 : ppmatEq B C) : ppmatEq A C

private theorem posM2 (lcn rn r0d r0n lcd rd : Pos) :
    lcn * lcn * rn * r0d + r0n * (lcd * lcd * rd)
      = r0n * (lcd * lcd * rd) + lcn * lcn * (rn * r0d)

private theorem seedShift (a b : BPair) (x y : Pos) :
    (a.scale x).scale y + b.scale x
      = (a.scale y + b.scale Pos.one).scale x

private theorem tailTail {A A' B : Mat} {As Bs : List Mat}
    {X X' R : MatQ} {Xt Rt : List MatQ} {n n' : Nat} {nt : List Nat}
    (h : tailRead (A :: A' :: As) (B :: Bs) (X :: X' :: Xt) (R :: Rt)
      (n :: n' :: nt)) :
    tailRead (A' :: As) Bs (X' :: Xt) Rt (n' :: nt)

private theorem posD5 (fn tn td fd md f W : Pos) :
    (fn * td + tn * fd) * md * (f * W)
      = fn * td * md * (f * W) + tn * fd * md * (f * W)

private theorem nuOf_entry (l : Nat) (f : Nat → BPair) (k : Nat)
    (hk : k < l) :
    ground.getAt BPair.unit (nuOf l f) k = BPair.norm (f k)

private theorem pnormEntry (P : poly.Poly) (k : Nat) (hk : k < P.length) :
    ground.getAt BPair.unit (poly.pnorm P) k
      = BPair.norm (ground.getAt BPair.unit P k)

private theorem negEntry (P : poly.Poly) (k : Nat) (hk : k < P.length) :
    ground.getAt BPair.unit (poly.pnorm (poly.neg P)) k
      = BPair.norm ((ground.getAt BPair.unit P k).swap)

private theorem magRefute (p q c d : Nat) (hcr : p + d = c + q)
    (hlo : c ≤ d + 2) (hhi : d ≤ c + 2)
    (hmag : q + 3 ≤ p ∨ p + 3 ≤ q) : False

private theorem headNarrow (l : Nat) (h1l : 1 < l) (F : Nat → Nat)
    (hcase : famCase l F) (hnat : 2 * F 0 = F 1 + 2) :
    F = serstable.fDiff 0 1

private theorem mulCounts (c p q : Nat) :
    (BPair.ofNat c * BPair.ofCounts p q).oneValue
      (BPair.ofCounts (c * p) (c * q))

private theorem cartOff (l i j : Nat) (h1 : ¬ j = i) (h2 : ¬ j = i + 1)
    (h3 : ¬ j + 1 = i) :
    (serstable.cartB l i j).oneValue (BPair.ofCounts 0 0)

private theorem narrowBelow (l m : Nat) (hml : m + 2 < l) :
    2 * serstable.fDiff (m + 1) (m + 2) m = 0
    ∧ serstable.nbB l (serstable.fDiff (m + 1) (m + 2)) m = 1

private theorem headColOne (l : Nat) (h2l : ¬ 2 = l) :
    2 * serstable.fDiff 0 1 1 = 0
    ∧ serstable.nbB l (serstable.fDiff 0 1) 1 = 1

private theorem headColTail (l q : Nat) (h1q : 1 ≤ q) (hq : q + 2 = l) :
    2 * serstable.fDiff 0 1 (q + 1) = 0
    ∧ serstable.nbB l (serstable.fDiff 0 1) (q + 1) = 0

private theorem tailRefuse (l q k : Nat) (hq : q + 2 = l) (hkq : k ≤ q)
    (F : Nat → Nat) (hcase : famCase l F) (hk2 : F k = 2) :
    F (q + 1) = 2 ∧ F q = 2

private theorem tailU2 (n : Nat) :
    row.thetaCount (sertables.tableB (n + 4))
      (raisedG (sertables.tableB (n + 4)) (nC (n + 4)) 1 (n + 3)) = 0

private theorem tailU3 (n : Nat) :
    row.thetaCount (sertables.tableB (n + 5))
      (raisedG (sertables.tableB (n + 5)) (nD (n + 5)) 1 (n + 4)) = 0

private theorem tailU4 (n : Nat) :
    row.thetaCount (sertables.tableB (n + 6))
      (raisedG (sertables.tableB (n + 6)) (nF (n + 6)) 1 (n + 5)) = 0

private theorem hitNB (p : Nat) :
    row.thetaCount (sertables.tableB (p + 3))
      (raisedG (sertables.tableB (p + 3)) (nB (p + 3)) 1 (p + 2)) = 1

private theorem hitNG (p : Nat) :
    row.thetaCount (sertables.tableB (p + 3))
      (raisedG (sertables.tableB (p + 3)) (nG (p + 3)) 1 (p + 2)) = 1

private theorem hitNH (p : Nat) :
    row.thetaCount (sertables.tableB (p + 4))
      (raisedG (sertables.tableB (p + 4)) (nH (p + 4)) 1 (p + 3)) = 1

private theorem memSumC (d a b : Nat) (hab : a < b) (hbl : b < d + 1) :
    (List.range (d + 1)).map (serstable.fSumC d a b)
      ∈ sertables.foldsC (d + 1)

private theorem memLongC (d a : Nat) (hal : a < d + 1) :
    (List.range (d + 1)).map (serstable.fLong d a)
      ∈ sertables.foldsC (d + 1)

private theorem nbMidC (l : Nat) (F : Nat → Nat) (m : Nat)
    (h2 : ¬ m + 2 = l) (h3 : ¬ m + 3 = l) :
    serstable.nbC l F (m + 1) = F m + F (m + 2)

private theorem nbSubC (l : Nat) (F : Nat → Nat) (m : Nat)
    (h2 : ¬ m + 2 = l) (h3 : m + 3 = l) :
    serstable.nbC l F (m + 1) = F m + 2 * F (m + 2)

private theorem cartOffC (l i j : Nat) (h1 : ¬ j = i) (h2 : ¬ j + 1 = i)
    (h3 : ¬ j = i + 1) :
    (serstable.cartC l i j).oneValue (BPair.ofCounts 0 0)

private theorem hitLongOne (k : Nat) :
    row.thetaCount (sertables.tableC (k + 6))
      (raisedG (sertables.tableC (k + 6)) (cE (k + 6)) 1 1) = 1

private theorem hitLongTwo (k : Nat) :
    row.thetaCount (sertables.tableC (k + 7))
      (raisedG (sertables.tableC (k + 7)) (cG (k + 7)) 1 2) = 1

private theorem memSumD (e a b : Nat) (hab : a < b) (hbe : b ≤ e) :
    (List.range (e + 2)).map (serstable.fSumD e a b)
      ∈ sertables.foldsD (e + 2)

private theorem cartForkTD (l i j : Nat) (h1 : ¬ j = i) (h2 : ¬ i + 1 = l)
    (h3 : j + 1 = l) (h4 : i + 3 = l) :
    (serstable.cartD l i j).oneValue (BPair.ofCounts 0 1)

private theorem sumSplitDt (e a k : Nat) :
    serstable.fSumDt e a k
      = serstable.fDiff a e k + serstable.fDiff (e + 1) (e + 2) k

private theorem dsumStep (e a b k : Nat) (hab : a < b) (hbe : b ≤ e)
    (h2 : serstable.fSumD e a b k = 2) (hk1 : k + 1 < e) :
    serstable.fSumD e a b (k + 1) = 2

private theorem narrowBelowD (l m : Nat) (hml : m + 4 < l) :
    2 * serstable.fDiff (m + 1) (m + 2) m = 0
    ∧ serstable.nbD l (serstable.fDiff (m + 1) (m + 2)) m = 1

private theorem headNarrowD (l : Nat) (hl : 4 ≤ l) (F : Nat → Nat)
    (hcase : famCaseD l F) (hnat : 2 * F 0 = F 1 + 2) :
    F = serstable.fDiff 0 1

private theorem headColOneD (l : Nat) (hl : 5 ≤ l) :
    2 * serstable.fDiff 0 1 1 = 0
    ∧ serstable.nbD l (serstable.fDiff 0 1) 1 = 1

private theorem headColVacD (l y : Nat) (h2y : 2 ≤ y) (hy3 : y + 3 < l) :
    2 * serstable.fDiff 0 1 y = 0
    ∧ serstable.nbD l (serstable.fDiff 0 1) y = 0

private theorem dtLow (e a k j : Nat) (hk : k < e)
    (h0 : serstable.fSumDt e a k = 0) (hjk : j ≤ k) :
    serstable.fSumDt e a j = 0

private theorem cartTailOff (k i j : Nat) (h4i : k + 4 ≤ i)
    (hj3 : j + 3 ≤ k + 4) :
    (serstable.cartD (k + 7) i j).oneValue (BPair.ofCounts 0 0)

private theorem spanRel_cast (n m : Nat) (L : elim.Mat)
    (v : List BPair) (h : elim.spanRel n L v) (hnm : n = m) :
    elim.spanRel m L v

private theorem wtAt_vacant (m : SMap) (t s : Nat)
    (h : ∀ e ∈ m, (e.1 == t && e.2.1 == s) = false) :
    (wtAt m t s).oneValue BPair.unit

private theorem sigmaP_C {v w : Nat} (hvw : v < w) {q : Nat × Nat}
    (h2 : q.2 = w) (h1 : q.1 < v) :
    sigmaP v w q = (q.1, v)

private theorem sigmaP_E {v w : Nat} (hvw : v < w) {q : Nat × Nat}
    (h2 : q.2 = w) (h1 : v < q.1) :
    sigmaP v w q = (v, q.1)

private theorem sigmaP_F {v w : Nat} {q : Nat × Nat}
    (h12 : q.1 < q.2) (h1 : q.1 = v) (h2 : q.2 < w) :
    sigmaP v w q = (q.2, w)

private theorem sigmaP_G {v w : Nat} (hvw : v < w) {q : Nat × Nat}
    (h1 : q.1 = v) (h2 : w < q.2) :
    sigmaP v w q = (w, q.2)

private theorem sigmaP_H {v w : Nat} (hvw : v < w) {q : Nat × Nat}
    (h1 : q.1 = w) (h2 : w < q.2) :
    sigmaP v w q = (v, q.2)

private theorem sigmaP_mem {d v w : Nat} (hvw : v < w) (hwd : w < d)
    {q : Nat × Nat} (hq : 0 < ground.countOf q (pairsOf d)) :
    0 < ground.countOf (sigmaP v w q) (pairsOf d)

private theorem sigmaP_invol {d v w : Nat} (hvw : v < w)
    {q : Nat × Nat} (hq : 0 < ground.countOf q (pairsOf d)) :
    sigmaP v w (sigmaP v w q) = q

private theorem flipC_sigmaP {d v w : Nat} (hvw : v < w)
    {q : Nat × Nat} (hq : 0 < ground.countOf q (pairsOf d)) :
    flipC v w (sigmaP v w q) = flipC v w q

private theorem countOf_exchAt {d : Nat} (S : List (Nat × Nat))
    (v w : Nat) {q : Nat × Nat}
    (hq : 0 < ground.countOf q (pairsOf d)) :
    ground.countOf q (exchAt d S v w)
      = if exMem S v w q = true then 1 else 0

private theorem takenAt_exchAt {d v w : Nat} (hvw : v < w)
    (S : List (Nat × Nat)) {q : Nat × Nat}
    (hq : 0 < ground.countOf q (pairsOf d)) :
    takenAt (exchAt d S v w) q
      = swapIx v w (takenAt S (sigmaP v w q))

private theorem takeAt_exchAt {d v w : Nat} (hvw : v < w)
    (hwd : w < d) (S : List (Nat × Nat)) (u : Nat) :
    takeAt d (exchAt d S v w) u = takeAt d S (swapIx v w u)

private theorem midV_sigmaP {d v w : Nat} (hvw : v < w)
    {q : Nat × Nat} (hq : 0 < ground.countOf q (pairsOf d)) :
    midV v w (sigmaP v w q) = midW v w q

private theorem sideOf_exchAt {d v w : Nat} (hvw : v < w)
    (hwd : w < d) {S : List (Nat × Nat)}
    (hS : 0 < ground.countOf S
      (ground.sublistsOf (pairsOf d))) :
    places.sideOf (exchAt d S v w) = ! places.sideOf S

private theorem containsB_exchAt {d : Nat} (S : List (Nat × Nat))
    (v w : Nat) {q : Nat × Nat}
    (hq : 0 < ground.countOf q (pairsOf d)) :
    ground.containsB (exchAt d S v w) q = exMem S v w q

private theorem exMem_exchAt {d v w : Nat} (hvw : v < w)
    (hwd : w < d) (S : List (Nat × Nat)) {q : Nat × Nat}
    (hq : 0 < ground.countOf q (pairsOf d)) :
    exMem (exchAt d S v w) v w q = ground.containsB S q

private theorem exchAt_invol {d v w : Nat} (hvw : v < w)
    (hwd : w < d) {S : List (Nat × Nat)}
    (hS : 0 < ground.countOf S
      (ground.sublistsOf (pairsOf d))) :
    exchAt d (exchAt d S v w) v w = S

private theorem takeAt_psiP_eq {d : Nat} {p : List Nat}
    (hp : 0 < ground.countOf p (places.perms d)) {v : Nat}
    (hv : v < d) :
    takeAt d (psiP d p) v = d - (places.posOf v p + 1)

private theorem sideOf_psiP {d : Nat} {p : List Nat}
    (hp : 0 < ground.countOf p (places.perms d)) :
