private theorem cellOneNeg (c : Nat) :
    (BPair.ofNat c * (BPair.ofNat 1).swap).oneValue
      (BPair.ofCounts 0 c)

private theorem cellTwoNeg (c : Nat) :
    (BPair.ofNat c * (BPair.ofNat 2).swap).oneValue
      (BPair.ofCounts 0 (2 * c))

private theorem cellOneNegZ (c : Nat) :
    (BPair.ofNat c * (BPair.ofNat 1).swap).oneValue
